declare(strict_types=1);
namespace OCA\Placetel\Native;
final class Views {
 public function __construct(private Analysis $analysis) {}
 public function queues(array $calls,array $queues,array $agents,array $coverage,?string $asOf,bool $connected): array {
  $now=time();$stamp=Analysis::stamp($asOf);$yesterday=Analysis::local($now)->setTime(0,0)->modify('-1 day')->getTimestamp();$records=array_values(array_filter($calls,static fn($c)=>!isset($c['source'])||($c['callType']??'')==='dail_in'));$open=array_values(array_filter($records,static fn($c)=>!$c['endedAt']&&Analysis::stamp($c['offeredAt'])>=$yesterday&&Analysis::stamp($c['offeredAt'])<=$now));$waiting=array_values(array_filter($open,static fn($c)=>$c['outcome']==='waiting'));$byDate=array_column($coverage,null,'date');$names=array_column($agents,'name','id');$queueIds=array_column($queues,'id');$stale=false;
  foreach($open as $c){$date=Analysis::local(Analysis::stamp($c['offeredAt']))->format('Y-m-d');if(isset($c['source'])&&in_array($c['outcome'],['accepted','waiting'],true)&&(!isset($byDate[$date])||!in_array($byDate[$date]['status'],['complete','imported'],true)||$now-Analysis::stamp($byDate[$date]['updatedAt'])>=30))$stale=true;}
  $result=[];foreach($queues as $queue){$w=array_values(array_filter($waiting,static fn($c)=>$c['queueId']===$queue['id']));usort($w,static fn($a,$b)=>strcmp($a['offeredAt'],$b['offeredAt'])?:strcmp($a['id'],$b['id']));$accepted=array_values(array_filter($records,static fn($c)=>$c['queueId']===$queue['id']&&$c['outcome']==='accepted'&&Analysis::stamp($c['acceptedAt']??$c['durationStart']??$c['referenceAt']??$c['offeredAt'])<=$now));$at=static fn($c)=>$c['acceptedAt']??$c['durationStart']??$c['referenceAt']??$c['offeredAt'];usort($accepted,static fn($a,$b)=>strcmp($at($b),$at($a))?:strcmp($a['id'],$b['id']));$recent=[];foreach(array_slice($accepted,0,3) as $c)$recent[]=['id'=>$c['id'],'caller'=>$this->analysis->phone($c['caller']),'at'=>$at($c),'timeBasis'=>$c['acceptedAt']?'accepted':(($c['durationStart']??null)?'queue-exit':'started'),'agentName'=>$names[$c['agentId']]??$c['agentName']??null,'endedAt'=>$c['endedAt']];$callers=[];foreach($w as $c)$callers[]=['id'=>$c['id'],'caller'=>$this->analysis->phone($c['caller']),'enteredAt'=>$c['offeredAt'],'agentName'=>$names[$c['agentId']]??$c['agentName']??null,'phase'=>($c['callStatus']??'')==='assigned'?'assigned':'waiting'];$result[]=['id'=>$queue['id'],'waiting'=>count($w),'active'=>count(array_filter($open,static fn($c)=>$c['queueId']===$queue['id']&&$c['outcome']==='accepted')),'longestWaitSeconds'=>$w&&is_finite($stamp)?max(array_map(static fn($c)=>max(0,$stamp-Analysis::stamp($c['offeredAt'])),$w)):null,'waitingCallers'=>$callers,'recentAccepted'=>$recent];}
  return ['asOf'=>$asOf,'serverNow'=>gmdate('c'),'fresh'=>$connected&&is_finite($stamp)&&$now-$stamp<30&&!$stale,'refreshIntervalSeconds'=>5,'unmappedWaiting'=>count(array_filter($waiting,static fn($c)=>!in_array($c['queueId'],$queueIds,true))),'queues'=>$result];
 }
 public function report(array $calls,array $queues,array $coverage,array $states,string $from,string $to,string $asOf): array {
  [$start,$end,$dates]=Analysis::range($from,$to,$asOf);$now=Analysis::stamp($asOf);$records=[];foreach($calls as $c)if(!isset($c['source'])||($c['callType']??'')==='dail_in')$records[$c['id']]=$c;$period=[];$accepted=[];$groups=[];
  foreach($records as $c){$phone=$this->analysis->phone($c['caller']);$at=$c['acceptedAt']??$c['durationStart']??$c['referenceAt']??$c['offeredAt'];if($c['outcome']==='accepted'&&$phone&&Analysis::stamp($at)<=$now)$accepted[json_encode([$c['queueId'],$phone])][]=$at;$t=Analysis::stamp($c['acceptedAt']??$c['referenceAt']??$c['offeredAt']);if($t<$start||$t>=$end)continue;$period[]=$c;if($c['outcome']==='missed'&&$c['endedAt']&&Analysis::stamp($c['endedAt'])<=$now){$key=hash('sha256',json_encode([$c['queueId'],$phone??$c['id']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$groups[$key][]=$c;}}
  $callbacks=[];foreach($groups as $key=>$rows){usort($rows,static fn($a,$b)=>strcmp($b['endedAt'],$a['endedAt'])?:strcmp($a['id'],$b['id']));$last=$rows[0];$phone=$this->analysis->phone($last['caller']);$times=$phone?($accepted[json_encode([$last['queueId'],$phone])]??[]):[];sort($times);$later=null;foreach($times as $t)if(Analysis::stamp($t)>=Analysis::stamp($last['endedAt'])){$later=$t;break;}$saved=$states[$key]??null;$callbacks[]=['key'=>$key,'caller'=>$phone,'queueId'=>$last['queueId'],'lastAt'=>$last['endedAt'],'attempts'=>count($rows),'latestId'=>$last['id'],'state'=>$saved&&$saved['latestId']===$last['id']?$saved['state']:'open','note'=>$saved['note']??'','laterAcceptedAt'=>$later];}usort($callbacks,static fn($a,$b)=>strcmp($b['lastAt'],$a['lastAt']));$ids=array_values(array_unique(array_merge(array_column($queues,'id'),array_column($period,'queueId'))));$reach=[];
  foreach($ids as $id){$r=['queueId'=>$id,'accepted'=>0,'failedAttempts'=>0,'cancelledAttempts'=>0,'uniqueFailed'=>0,'unknownCallerAttempts'=>0];$unique=[];foreach($period as $c){if($c['queueId']!==$id)continue;if($c['outcome']==='accepted')$r['accepted']++;if($c['outcome']==='missed'){$r['failedAttempts']++;if(($c['callStatus']??'')==='cancelled')$r['cancelledAttempts']++;$phone=$this->analysis->phone($c['caller']);if($phone)$unique[$phone]=true;else $r['unknownCallerAttempts']++;}}$r['uniqueFailed']=count($unique);$reach[]=$r;}
  return ['from'=>$from,'to'=>$to,'asOf'=>$asOf,'callbacks'=>$callbacks,'reachability'=>$reach,'coverage'=>Analysis::coverage($coverage,$dates)];
 }
}
